<?php defined('VV_ROOT') || exit; $candidates=\VV\Redirects::candidates($vv);$rules=$vv->state['redirects']??[]; ?>
<section class="panel"><p class="eyebrow">WORDPRESS → CMS</p><h2><?=e(t('Des anciens liens vers vos contenus.','From old links to your content.'))?></h2><p><?=e(t('Les règles approuvées renvoient directement vers une page ou un article public du CMS. Aucune cible externe ni chaîne de redirections. Les règles inactives ou visant un contenu devenu privé ne sont pas appliquées.','Approved rules point directly to a public native page or post. No external targets or redirect chains. Inactive rules and rules whose target became private are not applied.'))?></p><div class="check-row"><span><?=e(t('Règles proposées / approuvées','Proposed / approved rules'))?></span><strong><?=count($candidates)?> / <?=count($rules)?></strong></div>
<?php if($candidates):?><?=action_form('redirects.report',t('Télécharger toutes les propositions','Download all proposals'),[],'secondary')?><details><summary><?=e(t('Examiner les chemins proposés','Review proposed paths'))?></summary><ul><?php foreach(array_slice($candidates,0,100) as $r):?><li><code><?=e($r['source'])?></code> → <?=e(\VV\Content::field($vv->state['contents'][$r['content_id']],'title'))?></li><?php endforeach;?></ul><p class="hint"><?=e(t('Aperçu limité aux 100 premières règles. L’approbation concerne toutes les règles proposées.','Preview limited to the first 100 rules. Approval applies to all proposed rules.'))?></p></details><?=action_form('redirects.approve',t('Approuver ces redirections','Approve these redirects'),['revision'=>\VV\WordPress::fingerprint($vv->state)],'primary',true)?><?php endif;?></section>
<section class="panel"><h2><?=e(t('Règles actives','Active rules'))?></h2><div class="table-scroll"><table><thead><tr><th><?=e(t('Ancien chemin','Old path'))?></th><th><?=e(t('Contenu','Content'))?></th><th><?=e(t('Retirer','Remove'))?></th></tr></thead><tbody><?php foreach(array_slice($rules,max(0,(int)val($_GET,'offset','0')),50) as $r):?><tr><td><code><?=e($r['source'])?></code></td><td><?=e(isset($vv->state['contents'][$r['content_id']])?\VV\Content::field($vv->state['contents'][$r['content_id']],'title'):t('Contenu supprimé','Deleted content'))?></td><td><?=action_form('redirects.delete',t('Retirer','Remove'),['source'=>$r['source']],'secondary small',true)?></td></tr><?php endforeach;?></tbody></table></div><div class="button-row"><?php $offset=max(0,(int)val($_GET,'offset','0'));if($offset>0):?><a class="button secondary" href="<?=e(admin_url('redirects',['offset'=>max(0,$offset-50)]))?>"><?=e(t('Précédent','Previous'))?></a><?php endif;if(count($rules)>$offset+50):?><a class="button secondary" href="<?=e(admin_url('redirects',['offset'=>$offset+50]))?>"><?=e(t('Suivant','Next'))?></a><?php endif;?></div></section>
